CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS organizations (id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text::text, name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text::text, email text NOT NULL UNIQUE, password_hash text NOT NULL, status text NOT NULL DEFAULT 'active' CHECK (status IN ('active','disabled')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS memberships (user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, role text NOT NULL CHECK (role IN ('owner','admin','manager','member','viewer')), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (user_id, organization_id));
CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text::text, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS invitations (id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text::text, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, email text NOT NULL, role text NOT NULL CHECK (role IN ('admin','manager','member','viewer')), token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, accepted_at timestamptz, invited_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS customers (id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text::text, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, name text NOT NULL, email text, phone text, external_ref text, status text NOT NULL DEFAULT 'active' CHECK (status IN ('active','inactive')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sites (id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text::text, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, customer_id TEXT REFERENCES customers(id) ON DELETE SET NULL, name text NOT NULL, address text, latitude double precision, longitude double precision, geojson jsonb, external_ref text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK ((latitude IS NULL AND longitude IS NULL) OR (latitude BETWEEN -90 AND 90 AND longitude BETWEEN -180 AND 180)));
CREATE TABLE IF NOT EXISTS work_orders (id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text::text, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, number text NOT NULL, title text NOT NULL, description text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'open' CHECK (status IN ('open','in_progress','blocked','completed','cancelled')), priority text NOT NULL DEFAULT 'normal' CHECK (priority IN ('low','normal','high','urgent')), customer_id TEXT REFERENCES customers(id) ON DELETE SET NULL, site_id TEXT REFERENCES sites(id) ON DELETE SET NULL, assigned_to TEXT REFERENCES users(id) ON DELETE SET NULL, team_name text, due_at timestamptz, created_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (organization_id, number));
CREATE TABLE IF NOT EXISTS assets (id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text::text, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, name text NOT NULL, asset_type text NOT NULL, external_ref text, status text NOT NULL DEFAULT 'active' CHECK (status IN ('active','inactive','retired')), site_id TEXT REFERENCES sites(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS locations (id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text::text, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, name text NOT NULL, latitude double precision, longitude double precision, geojson jsonb, created_at timestamptz NOT NULL DEFAULT now(), CHECK ((latitude IS NULL AND longitude IS NULL) OR (latitude BETWEEN -90 AND 90 AND longitude BETWEEN -180 AND 180)));
CREATE TABLE IF NOT EXISTS activity_log (id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text::text, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, actor_user_id TEXT REFERENCES users(id) ON DELETE SET NULL, entity_type text NOT NULL, entity_id TEXT NOT NULL, event_type text NOT NULL, message text NOT NULL, metadata_json jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS comments (id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text::text, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, work_order_id TEXT NOT NULL REFERENCES work_orders(id) ON DELETE CASCADE, actor_user_id TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, body text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS attachments (id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text::text, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, work_order_id TEXT REFERENCES work_orders(id) ON DELETE CASCADE, entity_type text NOT NULL, entity_id TEXT NOT NULL, storage_provider text NOT NULL CHECK (storage_provider IN ('local','s3_compatible')), storage_key text NOT NULL UNIQUE, file_name text NOT NULL, media_type text NOT NULL, bytes bigint NOT NULL CHECK (bytes >= 0), sha256 text NOT NULL, uploaded_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS notifications (id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text::text, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, channel text NOT NULL CHECK (channel IN ('in_app','email','webhook')), event_type text NOT NULL, title text NOT NULL, body text NOT NULL, status text NOT NULL CHECK (status IN ('queued','accepted','delivered','failed','read')), created_at timestamptz NOT NULL DEFAULT now(), read_at timestamptz);
CREATE TABLE IF NOT EXISTS webhook_endpoints (id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text::text, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, url text NOT NULL, secret_hash text NOT NULL, active boolean NOT NULL DEFAULT true, created_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS webhook_deliveries (id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text::text, endpoint_id TEXT NOT NULL REFERENCES webhook_endpoints(id) ON DELETE CASCADE, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, event_type text NOT NULL, payload_json jsonb NOT NULL, status text NOT NULL CHECK (status IN ('queued','accepted','delivered','failed')), attempts integer NOT NULL DEFAULT 0, response_code integer, last_error text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_log (id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text::text, organization_id TEXT, actor_user_id TEXT, action text NOT NULL, resource_type text NOT NULL, resource_id TEXT, metadata_json jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_memberships_org ON memberships(organization_id);
CREATE INDEX IF NOT EXISTS idx_work_orders_org_status ON work_orders(organization_id,status);
CREATE INDEX IF NOT EXISTS idx_work_orders_org_due ON work_orders(organization_id,due_at);
CREATE INDEX IF NOT EXISTS idx_assets_org ON assets(organization_id);
CREATE INDEX IF NOT EXISTS idx_sites_org ON sites(organization_id);
CREATE INDEX IF NOT EXISTS idx_locations_org ON locations(organization_id);
CREATE INDEX IF NOT EXISTS idx_activity_entity ON activity_log(organization_id,entity_type,entity_id,created_at);
CREATE INDEX IF NOT EXISTS idx_comments_wo ON comments(organization_id,work_order_id,created_at);
CREATE INDEX IF NOT EXISTS idx_attachments_entity ON attachments(organization_id,entity_type,entity_id,created_at);
CREATE INDEX IF NOT EXISTS idx_notifications_user ON notifications(organization_id,user_id,created_at);
CREATE INDEX IF NOT EXISTS idx_webhook_deliveries_endpoint ON webhook_deliveries(organization_id,endpoint_id,created_at);
CREATE INDEX IF NOT EXISTS idx_audit_org_created ON audit_log(organization_id,created_at DESC);

ALTER TABLE work_orders ADD COLUMN IF NOT EXISTS asset_id TEXT REFERENCES assets(id) ON DELETE SET NULL;
ALTER TABLE parts ADD COLUMN IF NOT EXISTS unit_cost numeric;
CREATE TABLE IF NOT EXISTS operational_financial_settings (organization_id TEXT PRIMARY KEY REFERENCES organizations(id) ON DELETE CASCADE, currency text NOT NULL DEFAULT 'USD', labor_cost_per_hour numeric, updated_at timestamptz NOT NULL DEFAULT now(), CHECK(labor_cost_per_hour IS NULL OR labor_cost_per_hour >= 0));
CREATE TABLE IF NOT EXISTS work_order_financials (work_order_id TEXT PRIMARY KEY REFERENCES work_orders(id) ON DELETE CASCADE, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, labor_hours numeric, revenue numeric, repeat_visit boolean NOT NULL DEFAULT false, updated_at timestamptz NOT NULL DEFAULT now(), CHECK(labor_hours IS NULL OR labor_hours >= 0), CHECK(revenue IS NULL OR revenue >= 0));
CREATE TABLE IF NOT EXISTS contracts (id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text::text, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, customer_id TEXT NOT NULL REFERENCES customers(id) ON DELETE CASCADE, name text NOT NULL, reference text, starts_at timestamptz NOT NULL, ends_at timestamptz, sla_priority text, active boolean NOT NULL DEFAULT true, created_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS asset_warranties (id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text::text, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, asset_id TEXT NOT NULL REFERENCES assets(id) ON DELETE CASCADE, provider text, starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, terms text, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS maintenance_plans (id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text::text, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, asset_id TEXT NOT NULL REFERENCES assets(id) ON DELETE CASCADE, name text NOT NULL, interval_days integer NOT NULL CHECK(interval_days > 0), next_due_at timestamptz NOT NULL, procedure_id TEXT REFERENCES procedure_definitions(id) ON DELETE SET NULL, active boolean NOT NULL DEFAULT true, created_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS maintenance_runs (id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text::text, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, plan_id TEXT NOT NULL REFERENCES maintenance_plans(id) ON DELETE CASCADE, work_order_id TEXT REFERENCES work_orders(id) ON DELETE SET NULL, due_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(plan_id,due_at));
CREATE TABLE IF NOT EXISTS safety_checklists (id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text::text, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, name text NOT NULL, work_type text NOT NULL, items_json jsonb NOT NULL, active boolean NOT NULL DEFAULT true, created_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS safety_acknowledgements (id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text::text, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, checklist_id TEXT NOT NULL REFERENCES safety_checklists(id) ON DELETE CASCADE, work_order_id TEXT NOT NULL REFERENCES work_orders(id) ON DELETE CASCADE, actor_user_id TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, answers_json jsonb NOT NULL, acknowledged_at timestamptz NOT NULL DEFAULT now(), UNIQUE(checklist_id,work_order_id,actor_user_id));
CREATE INDEX IF NOT EXISTS idx_wo_asset ON work_orders(organization_id,asset_id);
CREATE INDEX IF NOT EXISTS idx_contracts_org_customer ON contracts(organization_id,customer_id,active);
CREATE INDEX IF NOT EXISTS idx_warranty_org_asset ON asset_warranties(organization_id,asset_id,active,ends_at);
CREATE INDEX IF NOT EXISTS idx_pm_org_due ON maintenance_plans(organization_id,active,next_due_at);
CREATE INDEX IF NOT EXISTS idx_safety_ack_org_wo ON safety_acknowledgements(organization_id,work_order_id,acknowledged_at);
